.enhanced-text {
  font-family: "My Variable Font", sans-serif;
  /* Enable standard ligatures (on by default for many fonts) */
  font-feature-settings: "liga" on; 
  /* Enable discretionary ligatures */
  font-feature-settings: "dlig" on;
  /* Or combine multiple features */
  font-feature-settings: "liga" on, "dlig" on, "salt" 1;
  /* For specific stylistic set 10 */
  font-feature-settings: "ss10" on; 
  /* Fallback for older browsers (or use font-variant-ligatures) */
  -webkit-font-feature-settings: "dlig" 1; 
  -moz-font-feature-settings: "dlig" 1;
  /* Modern shorthand for some features */
  font-variant-ligatures: common-ligatures discretionary-ligatures;
}
